onClick:
{{
  (async () => {
    if (Tabs1.selectedTab.includes('Flotte')) {
      // 🚜 Onglet Flotte & Matériel : On ajoute un nouvel engin au parc
      await resetWidget('Modal_Add_Machine_Loc', true);
      showModal('Modal_Add_Machine_Loc');
    } else {
      // 📋 Onglet Contrats ou Planning : On fait une nouvelle location

      // 1. On vide le cache des anciens clients sélectionnés
      await storeValue('nouveau_client_id', '');
      await storeValue('nouvelle_machine_id', '');

      // 2. On nettoie la fenêtre de location
      await resetWidget('modal_add_location', true);

      // 3. On charge la liste des clients et des machines
      await Get_Clients_Options.run();
      await Get_Machines_Location.run(); // 🟢 Ajout pour charger le catalogue des engins

      // 4. On ouvre la fenêtre
      showModal('modal_add_location');
    }
  })()
}}
